#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>

#define SIZE 2516
#define SCREEN_HEIGHT 240
#define SCREEN_WIDTH 320

// Graph dimensions and padding
#define GRAPH_HEIGHT 210 
#define GRAPH_HEIGHT_PADDING 20   // from bottom
#define GRAPH_WIDTH 300
#define GRAPH_WIDTH_PADDING 40    // from left

#define SELECTED_YEAR_START 2019
#define YEAR_RANGE 4  // number of years to include

// Sample mode: 0 = day (every point), 1 = week (last day of week), 2 = month (last day of month)
#define SAMPLE_MODE 1


#define WHITE 0xFFFF
#define BLACK 0x0000
#define KEY_BASE 0xFF200050
#define EDGE_CAPTURE 0xFF20005C
#define CHAR_BUFFER_BASE 0x09000000

//---------------------------------------------------------------------
// Stock structure: holds two arrays (dates and values) plus a name.
// We also include a parsed_dates array for easier date filtering.
//---------------------------------------------------------------------
typedef struct {
    const char **dates;   // Array of date strings (e.g., "1/2/2015")
    float *values;        // Array of stock values
    char *name;           // Stock name
    int size;             // Number of data points
	short int color;
    time_t *parsed_dates; // Array of parsed dates (computed from dates)
} Stock;

//---------------------------------------------------------------------
// Function declarations
//---------------------------------------------------------------------
void plot_pixel(int x, int y, short int line_color);
void clear_screen(void);
void draw_stock(Stock *s);
void draw_line(int x0, int y0, int x1, int y1, short int line_color);
void swap(int* x, int* y);
time_t parse_date(const char *date_str);
void init_stock(Stock *s);

void write_char(int x, int y, char c);
void print_string(int x, int y, const char *str);

void calculate_x_divisions(const char *global_date[], int size);
void calculate_y_divisions(float arr[], int size, float divisions[]);
int map_vga_y_to_char_y(int vga_y);
int map_vga_x_to_char_x(int vga_x);



// Data processing functions
int filter_data(Stock *s, int *filter_indices, int start_year, int yr_range);
int sample_data(Stock *s, int *sample_indices, int *filter_indices, int filter_count, int sample_mode);
int select_window(int *window_indices, int *sample_indices, int sample_count, int window_size);
void compute_sample_min_max(Stock *s, int *sample_indices, int count, float *min, float *max);
void normalize_samples(Stock *s, int *sample_indices, int count, float sample_min, float sample_max, int *normalized);
void draw_graph(int *normalized, int count, short int color);

//---------------------------------------------------------------------
// Global variable: pixel buffer start address.
//---------------------------------------------------------------------
volatile int pixel_buffer_start; // variable for frame buffer

